package com.craftcost;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a real RuneLite client with this plugin already loaded, for local
 * testing. Run via the Gradle "run" task (or straight from your IDE).
 */
public class CraftCostPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CraftCostPlugin.class);
		RuneLite.main(args);
	}
}

package com.craftcost;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Every recipe the plugin knows about, gathered from one list per skill.
 * <p>
 * Each skill lives in its own file (e.g. {@link HerbloreRecipes}) so no single
 * file grows unmanageable as coverage expands, and so a skill can be worked on
 * without touching the others. To add a skill, create its
 * {@code XxxRecipes.RECIPES} list and add one line to {@link #RECIPES} below -
 * nothing else in the plugin needs to change, since the panel's search box and
 * the Grand Exchange auto-detect both read straight from this list.
 * <p>
 * Recipes reference items through RuneLite's {@code ItemID} constants rather
 * than raw numbers, so a mistyped item is a compile error instead of a silently
 * wrong price. Only items that are Grand Exchange tradeable belong here: an
 * untradeable ingredient has no price for the plugin to total up.
 */
final class RecipeDatabase
{
	static final List<Recipe> RECIPES;

	static
	{
		List<Recipe> all = new ArrayList<>();
		all.addAll(HerbloreRecipes.RECIPES);
		RECIPES = Collections.unmodifiableList(all);
	}

	/**
	 * @return the recipe whose finished item matches this id, or null if
	 * it's not one we know how to make.
	 */
	static Recipe findByItemId(int itemId)
	{
		for (Recipe recipe : RECIPES)
		{
			if (recipe.getItemId() == itemId)
			{
				return recipe;
			}
		}
		return null;
	}

	private RecipeDatabase()
	{
	}
}

package com.craftcost;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CraftCostConfig.CONFIG_GROUP)
public interface CraftCostConfig extends Config
{
	String CONFIG_GROUP = "craftcost";

	@ConfigItem(
		keyName = "autoShowGeItem",
		name = "Auto-show GE item",
		description = "When you're looking at an item's price at the Grand Exchange and it's one of your known recipes, " +
			"automatically add it to the watchlist panel."
	)
	default boolean autoShowGeItem()
	{
		return false;
	}

	@ConfigItem(
		keyName = "countBank",
		name = "Count bank items",
		description = "Include items sitting in your bank (not just your inventory) as 'owned' when working out how many you'd still need to buy. " +
			"Note the client only knows your bank's contents once you've opened your bank at least once this session."
	)
	default boolean countBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "countInventory",
		name = "Count inventory items",
		description = "Include items in your inventory as 'owned' when working out how many you'd still need to buy."
	)
	default boolean countInventory()
	{
		return true;
	}
}

package com.craftcost;

import java.util.List;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Describes how to make one tradeable item (the "output") from a fixed list
 * of other tradeable items (the "ingredients"), plus what it costs to actually
 * make it in-game: the skill and level it trains, the XP per action, roughly
 * how long one action takes, and any quest gating that skill entirely.
 * <p>
 * Only items that RuneLite can quote a Grand Exchange price for should be used
 * as ingredients - if an ingredient itself needs to be crafted from something
 * else (e.g. an unfinished potion), either add its own {@link Recipe} to
 * {@link RecipeDatabase} and let the panel flatten the two, or just list its
 * own base materials directly here instead.
 */
@Value
public class Recipe
{
	int itemId;
	String itemName;
	List<Ingredient> ingredients;
	Skill skill;
	int levelRequired;
	double xpPerAction;
	int ticksPerAction;
	Quest requiredQuest;

	/**
	 * How many of the finished item a single action produces. Usually 1, but
	 * some recipes yield a batch - making herb tar, for instance, turns 15
	 * swamp tar and one herb into 15 tars in one go. Ingredient costs, XP and
	 * time are all charged per action, not per finished item.
	 */
	int outputQuantity;

	@Override
	public String toString()
	{
		// used by the JComboBox renderer
		return itemName;
	}
}

package com.craftcost;

import java.awt.BorderLayout;
import java.awt.Color;
